<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Bowl</title>
<style>
  :root{
    --ink:#07060a;
    --warm:#ff9a48;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html,body{height:100%;overflow:hidden;background:var(--ink)}
  body{
    background:
      radial-gradient(120% 90% at 50% 62%, #1a1114 0%, #0d0a0e 45%, #060508 100%);
    color:#fff;
    touch-action:none;
    -webkit-tap-highlight-color:transparent;
  }
  .stage{
    position:fixed; inset:0;
    display:grid; place-items:center;
    perspective:1400px;
    perspective-origin:50% 55%;
  }
  .tilt{
    width:100%; height:100%;
    transform-style:preserve-3d;
    will-change:transform;
    transition:transform .9s cubic-bezier(.16,.7,.2,1);
  }
  svg.bowl{
    width:100%; height:100%;
    display:block;
    overflow:visible;
  }
  canvas#fx{
    position:fixed; inset:0;
    width:100%; height:100%;
    pointer-events:none;
  }
  /* grain / vignette over everything */
  .vignette{
    position:fixed; inset:-10%;
    pointer-events:none;
    background:radial-gradient(65% 55% at 50% 55%, rgba(0,0,0,0) 40%, rgba(0,0,0,.55) 78%, rgba(0,0,0,.9) 100%);
  }

  /* --- gentle life --- */
  .float{
    transform-box:fill-box;
    transform-origin:50% 50%;
    animation:bob var(--dur,6s) ease-in-out var(--delay,0s) infinite alternate;
    will-change:transform;
  }
  @keyframes bob{
    from{transform:translate(-1.1px,-1.4px) rotate(-.35deg)}
    to  {transform:translate(1.2px,1.6px) rotate(.4deg)}
  }
  .shimmer{animation:shimmer 9s ease-in-out infinite alternate}
  @keyframes shimmer{from{opacity:.28}to{opacity:.62}}
  .shimmer2{animation:shimmer2 13s ease-in-out infinite alternate}
  @keyframes shimmer2{from{opacity:.5;transform:translateX(-6px)}to{opacity:.16;transform:translateX(8px)}}
  .emberglow{animation:ember 7.5s ease-in-out infinite alternate;transform-box:fill-box;transform-origin:50% 50%}
  @keyframes ember{from{opacity:.55;transform:scale(.985)}to{opacity:.85;transform:scale(1.03)}}
  .ripple{animation:ripple 2.2s cubic-bezier(.2,.6,.3,1) forwards}
  @keyframes ripple{
    0%{opacity:.5;transform:scale(.05)}
    100%{opacity:0;transform:scale(1)}
  }

  @media (prefers-reduced-motion: reduce){
    *,*::before,*::after{animation:none !important;transition:none !important}
    .tilt{transform:none !important}
  }
</style>
</head>
<body>
<div class="stage">
  <div class="tilt" id="tilt">
    <svg class="bowl" viewBox="0 0 1000 760" preserveAspectRatio="xMidYMid meet" aria-hidden="true">
      <defs>
        <radialGradient id="airGlow" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stop-color="#ff9c4a" stop-opacity=".30"/>
          <stop offset="45%" stop-color="#c9541f" stop-opacity=".13"/>
          <stop offset="100%" stop-color="#3a0d06" stop-opacity="0"/>
        </radialGradient>
        <radialGradient id="tableGlow" cx="50%" cy="50%" r="50%">
          <stop offset="0%" stop-color="#ff8a3c" stop-opacity=".22"/>
          <stop offset="100%" stop-color="#ff6a1e" stop-opacity="0"/>
        </radialGradient>

        <linearGradient id="ceramic" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%"  stop-color="#3a2c2e"/>
          <stop offset="26%" stop-color="#241a1e"/>
          <stop offset="70%" stop-color="#120d11"/>
          <stop offset="100%" stop-color="#080609"/>
        </linearGradient>
        <linearGradient id="ceramicSide" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%"   stop-color="#5b4038" stop-opacity=".55"/>
          <stop offset="18%"  stop-color="#000000" stop-opacity="0"/>
          <stop offset="76%"  stop-color="#000000" stop-opacity="0"/>
          <stop offset="100%" stop-color="#8a4f2c" stop-opacity=".5"/>
        </linearGradient>
        <linearGradient id="rimLight" x1="0" y1="0" x2="1" y2="0">
          <stop offset="0%"   stop-color="#ffb877" stop-opacity="0"/>
          <stop offset="22%"  stop-color="#ffcf9c" stop-opacity=".55"/>
          <stop offset="50%"  stop-color="#fff0d8" stop-opacity=".8"/>
          <stop offset="78%"  stop-color="#ffc287" stop-opacity=".5"/>
          <stop offset="100%" stop-color="#ff9c52" stop-opacity="0"/>
        </linearGradient>

        <radialGradient id="broth" cx="46%" cy="38%" r="72%">
          <stop offset="0%"   stop-color="#b8682a"/>
          <stop offset="34%"  stop-color="#8a4418"/>
          <stop offset="68%"  stop-color="#4d2210"/>
          <stop offset="100%" stop-color="#24100a"/>
        </radialGradient>
        <radialGradient id="brothHot" cx="50%" cy="50%" r="50%">
