        </linearGradient>
        <radialGradient id="shroom" cx="38%" cy="30%" r="75%">
          <stop offset="0%" stop-color="#8e6440"/>
          <stop offset="60%" stop-color="#573venus" stop-opacity="1"/>
          <stop offset="100%" stop-color="#33190f"/>
        </radialGradient>
        <linearGradient id="nori" x1="0" y1="0" x2="0.4" y2="1">
          <stop offset="0%" stop-color="#20342e"/>
          <stop offset="45%" stop-color="#101d1b"/>
          <stop offset="100%" stop-color="#060c0c"/>
        </linearGradient>
        <linearGradient id="leaf" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#7fae52"/>
          <stop offset="55%" stop-color="#4a7c33"/>
          <stop offset="100%" stop-color="#2b4c20"/>
        </linearGradient>
        <linearGradient id="stem" x1="0" y1="0" x2="0" y2="1">
          <stop offset="0%" stop-color="#eef3d8"/>
          <stop offset="100%" stop-color="#b9c791"/>
        </linearGradient>

        <filter id="soft" x="-60%" y="-60%" width="220%" height="220%">
          <feGaussianBlur stdDeviation="26"/>
        </filter>
        <filter id="softer" x="-80%" y="-80%" width="260%" height="260%">
          <feGaussianBlur stdDeviation="48"/>
        </filter>
        <filter id="tiny" x="-40%" y="-40%" width="180%" height="180%">
          <feGaussianBlur stdDeviation="2.2"/>
        </filter>
        <filter id="innerShade" x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation="14"/>
        </filter>

        <clipPath id="brothClip">
          <ellipse cx="500" cy="398" rx="268" ry="72"/>
        </clipPath>
      </defs>

      <!-- ambient warmth behind the bowl -->
      <g id="light">
        <ellipse cx="500" cy="380" rx="430" ry="330" fill="url(#airGlow)" filter="url(#softer)"/>
        <ellipse cx="500" cy="655" rx="330" ry="70" fill="url(#tableGlow)" filter="url(#soft)" class="emberglow"/>
      </g>

      <!-- shadow pooled under the bowl -->
      <ellipse cx="500" cy="662" rx="300" ry="48" fill="#000" opacity=".65" filter="url(#soft)"/>

      <!-- bowl body -->
      <g id="vessel">
        <path d="M210,398 A290,84 0 0 1 790,398 C787,548 688,650 500,650 C312,650 213,548 210,398 Z" fill="url(#ceramic)"/>
        <path d="M210,398 A290,84 0 0 1 790,398 C787,548 688,650 500,650 C312,650 213,548 210,398 Z" fill="url(#ceramicSide)"/>
        <!-- subtle glaze band -->
        <path d="M238,470 C300,530 400,566 500,566 C600,566 700,530 762,470"
              fill="none" stroke="#ffb478" stroke-opacity=".07" stroke-width="16" filter="url(#tiny)"/>
        <!-- rim -->
        <ellipse cx="500" cy="398" rx="290" ry="84" fill="none" stroke="#0b0709" stroke-width="16"/>
        <ellipse cx="500" cy="396" rx="290" ry="84" fill="none" stroke="url(#rimLight)" stroke-width="4.5"/>
      </g>

      <!-- broth -->
      <g id="surface">
        <ellipse cx="500" cy="398" rx="272" ry="74" fill="#150a07"/>
        <ellipse cx="500" cy="398" rx="268" ry="72" fill="url(#broth)"/>
        <g clip-path="url(#brothClip)">
          <ellipse cx="470" cy="386" rx="200" ry="58" fill="url(#brothHot)" class="shimmer"/>
          <!-- inner wall shade -->
          <ellipse cx="500" cy="398" rx="268" ry="72" fill="none" stroke="#1a0a05" stroke-width="34" opacity=".85" filter="url(#innerShade)"/>
          <!-- broth sheen -->
          <path d="M300,372 C360,352 460,348 540,362" fill="none" stroke="#ffd9a6" stroke-opacity=".22" stroke-width="5" filter="url(#tiny)" class="shimmer2"/>
          <path d="M560,424 C620,418 665,408 700,394" fill="none" stroke="#ffc98d" stroke-opacity=".14" stroke-width="4" filter="url(#tiny)" class="shimmer"/>
          <g id="ripples"></g>
          <g id="oil"></g>
        </g>
      </g>

      <!-- toppings -->
      <g id="food" clip-path="none">

        <!-- noodle nest -->
        <g class="float" style="--dur:7.5s;--delay:-1s">
          <g fill="none" stroke="#3a2410" stroke-opacity=".55" stroke-width="11" stroke-linecap="round">
            <path d="M336,398 C392,362 470,356 526,390"/>
            <path d="M356,420 C412,384 500,378 566,410"/>
            <path d="M346,376 C404,344 486,340 548,370"/>
            <path d="M374,436 C432,410 522,404 588,428"/>
          </g>
          <g fill="none" stroke="url(#noodle)" stroke-width="8.5" stroke-linecap="round">
            <path d="M334,394 C390,358 468,352 524,386"/>
            <path d="M354,416 C410,380 498,374 564,406"/>
            <path d="M344,372 C402,340 484,336 546,366"/>
            <path d="M372,432 C430,406 520,400 586,424"/>
            <path d="M318,410 C352,396 392,390 424,398"/>
            <path d="M400,352 C450,332 512,332 556,350"/>
          </g>
          <g fill="none" stroke="#fff2cf" stroke-opacity=".45" stroke-width="2" stroke-linecap="round">
            <path d="M348,388 C396,358 462,352 512,378"/>
            <path d="M362,410 C412,380 492,374 552,400"/>
          </g>
        </g>

        <!-- nori sheet, leaning -->
        <g transform="translate(322,332) rotate(-13)">
          <g class="float" style="--dur:8.5s;--delay:-3s">
            <path d="M0,0 L92,-14 C98,20 100,58 96,92 L4,106 C-2,72 -2,34 0,0 Z" fill="url(#nori)"/>
            <path d="M0,0 L92,-14 C98,20 100,58 96,92" fill="none" stroke="#4c7a63" stroke-opacity=".35" stroke-width="2"/>
            <path d="M14,10 C40,44 46,66 42,96" fill="none" stroke="#6f9c85" stroke-opacity=".16" stroke-width="6"/>
          </g>
        </g>

        <!-- shiitake slices -->
        <g transform="translate(352,414)">
          <g class="float" style="--dur:6.4s;--delay:-2.2s">
            <ellipse cx="0" cy="4" rx="46" ry="20" fill="#2a1409" opacity=".7"/>
            <ellipse cx="0" cy="0" rx="46" ry="20" fill="#6b4527"/>
            <ellipse cx="-6" cy="-4" rx="34" ry="12" fill="#8a5c34" opacity=".8"/>
            <path d="M-22,-8 L18,8 M14,-12 L-18,10" stroke="#f2dcbb" stroke-opacity=".5" stroke-width="3" stroke-linecap="round"/>
          </g>
        </g>
        <g transform="translate(626,368)">
          <g class="float" style="--dur:7.1s;--delay:-4.5s">
            <ellipse cx="0" cy="4" rx="40" ry="17" fill="#2a1409" opacity=".7"/>
            <ellipse cx="0" cy="0" rx="40" ry="17" fill="#5f3d22"/>
            <ellipse cx="-4" cy="-3" rx="29" ry="10" fill="#7e522e" opacity=".8"/>
            <path d="M-18,-6 L16,6 M12,-10 L-15,8" stroke="#f2dcbb" stroke-opacity=".45" stroke-width="2.6" stroke-linecap="round"/>
          </g>
        </g>

        <!-- tofu cubes -->
        <g transform="translate(556,340)">
          <g class="float" style="--dur:6.8s;--delay:-0.6s">
            <ellipse cx="34" cy="42" rx="42" ry="14" fill="#1c0c06" opacity=".6"/>
            <path d="M0,0 L34,-15 L68,0 L34,15 Z" fill="url(#tofuTop)"/>
            <path d="M0,0 L0,24 L34,39 L34,15 Z" fill="url(#tofuL)"/>
            <path d="M68,0 L68,24 L34,39 L34,15 Z" fill="url(#tofuR)"/>
            <path d="M0,0 L34,-15 L68,0" fill="none" stroke="#fff8e6" stroke-opacity=".6" stroke-width="1.6"/>
            <path d="M2,20 L32,34" stroke="#c79a56" stroke-opacity=".5" stroke-width="2"/>
          </g>
        </g>
        <g transform="translate(408,336)">
          <g class="float" style="--dur:7.9s;--delay:-3.8s">
            <ellipse cx="26" cy="34" rx="34" ry="12" fill="#1c0c06" opacity=".55"/>
            <path d="M0,0 L26,-11 L52,0 L26,11 Z" fill="url(#tofuTop)"/>
            <path d="M0,0 L0,19 L26,30 L26,11 Z" fill="url(#tofuL)"/>
            <path d="M52,0 L52,19 L26,30 L26,11 Z" fill="url(#tofuR)"/>
            <path d="M0,0 L26,-11 L52,0" fill="none" stroke="#fff8e6" stroke-opacity=".5" stroke-width="1.4"/>
          </g>
        </g>

        <!-- bok choy -->
        <g transform="translate(474,432)">
          <g class="float" style="--dur:6.1s;--delay:-1.8s">
            <ellipse cx="0" cy="10" rx="52" ry="16" fill="#12180a" opacity=".55"/>
