            <path d="M-52,6 C-30,2 -4,0 26,-4" fill="none" stroke="#cfe3a6" stroke-opacity=".4" stroke-width="3"/>
            <path d="M-56,8 C-40,14 -12,18 14,16 C0,22 -34,22 -56,8 Z" fill="url(#stem)"/>
          </g>
        </g>

        <!-- corn -->
        <g id="corn"></g>
        <!-- scallions + sesame + chili flakes -->
