        <!-- rising heat highlight on the food -->
        <ellipse cx="500" cy="392" rx="230" ry="60" fill="url(#brothHot)" opacity=".18" style="mix-blend-mode:screen"/>
      </g>

      <!-- front rim over the food for depth -->
      <path d="M212,404 C232,462 350,486 500,486 C650,486 768,462 788,404
               C788,470 660,506 500,506 C340,506 212,470 212,404 Z"
            fill="#0c0709" opacity=".0"/>
      <path d="M210,398 A290,84 0 0 0 790,398" fill="none" stroke="#0d090b" stroke-width="15"/>
      <path d="M214,404 A286,80 0 0 0 786,404" fill="none" stroke="#ffbe86" stroke-opacity=".28" stroke-width="3"/>

      <!-- steam origin marker (invisible) -->
      <ellipse id="anchor" cx="500" cy="390" rx="240" ry="56" fill="none"/>
    </svg>
  </div>
</div>
<canvas id="fx"></canvas>
<div class="vignette"></div>

<script>
(function(){
  "use strict";

  var reduceQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
  var reduce = reduceQuery.matches;

  /* ---------- deterministic-ish random ---------- */
  var seed = 20260904;
  function rnd(){ seed = (seed * 1664525 + 1013904223) % 4294967296; return seed / 4294967296; }
  function rr(a,b){ return a + (b-a)*rnd(); }

  var SVGNS = 'http://www.w3.org/2000/svg';
  function el(name, attrs){
    var n = document.createElementNS(SVGNS, name);
    for (var k in attrs) n.setAttribute(k, attrs[k]);
    return n;
  }

  /* ---------- scatter garnish across the broth ellipse ---------- */
  var CX = 500, CY = 398, RX = 250, RY = 62;
  function scatter(count, minR, maxR, fn){
    var made = 0, guard = 0;
    while (made < count && guard++ < count * 40){
      var a = rr(0, Math.PI*2), r = Math.sqrt(rr(minR*minR, maxR*maxR));
      var x = CX + Math.cos(a) * RX * r;
      var y = CY + Math.sin(a) * RY * r;
      if (fn(x, y, r)) made++;
    }
  }

  var cornG = document.getElementById('corn');
  scatter(26, .25, .95, function(x,y){
    if (x > 300 && x < 620 && y > 330 && y < 450) return false; // keep the nest readable
    var g = el('g', {transform:'translate(' + x.toFixed(1) + ',' + y.toFixed(1) + ') rotate(' + rr(-25,25).toFixed(1) + ')'});
    var inner = el('g', {'class':'float'});
    inner.style.setProperty('--dur', rr(4.5, 8.5).toFixed(2) + 's');
    inner.style.setProperty('--delay', (-rr(0,7)).toFixed(2) + 's');
    var s = rr(.85, 1.25);
    inner.appendChild(el('ellipse', {cx:0, cy:3*s, rx:9*s, ry:5*s, fill:'#2a1607', opacity:.55}));
    inner.appendChild(el('ellipse', {cx:0, cy:0, rx:9*s, ry:6.4*s, fill:'#f0b93c'}));
    inner.appendChild(el('ellipse', {cx:-2*s, cy:-2*s, rx:4.6*s, ry:2.9*s, fill:'#ffe28a', opacity:.85}));
    g.appendChild(inner); cornG.appendChild(g);
    return true;
  });

  var garnish = document.getElementById('garnish');
  // scallion rings
  scatter(34, .15, 1.0, function(x,y){
    var g = el('g', {transform:'translate(' + x.toFixed(1) + ',' + y.toFixed(1) + ') rotate(' + rr(-30,30).toFixed(1) + ')'});
    var inner = el('g', {'class':'float'});
    inner.style.setProperty('--dur', rr(4, 9).toFixed(2) + 's');
    inner.style.setProperty('--delay', (-rr(0,8)).toFixed(2) + 's');
    var s = rr(.7, 1.35);
    inner.appendChild(el('ellipse', {cx:0, cy:2.5*s, rx:8*s, ry:4.6*s, fill:'#16240c', opacity:.5}));
    inner.appendChild(el('ellipse', {cx:0, cy:0, rx:8*s, ry:5*s, fill:'#8dc158'}));
    inner.appendChild(el('ellipse', {cx:0, cy:0, rx:3.6*s, ry:2.1*s, fill:'#e9f6cd'}));
    inner.appendChild(el('ellipse', {cx:-1.6*s, cy:-1.6*s, rx:3*s, ry:1.5*s, fill:'#c9e79a', opacity:.6}));
    g.appendChild(inner); garnish.appendChild(g);
    return true;
  });
  // sesame seeds
  scatter(30, .1, 1.0, function(x,y){
    var s = rr(.7,1.1);
    garnish.appendChild(el('ellipse', {
      cx:x.toFixed(1), cy:y.toFixed(1), rx:(3.4*s).toFixed(2), ry:(2.1*s).toFixed(2),
      transform:'rotate(' + rr(-40,40).toFixed(1) + ' ' + x.toFixed(1) + ' ' + y.toFixed(1) + ')',
      fill: rnd() > .45 ? '#f3e7cb' : '#3c3226', opacity:.9
    }));
    return true;
  });
  // chili flakes
  scatter(22, .2, 1.0, function(x,y){
    var s = rr(.6,1.2);
    garnish.appendChild(el('rect', {
      x:(x-2.6*s).toFixed(1), y:(y-1.6*s).toFixed(1), width:(5.2*s).toFixed(1), height:(3.2*s).toFixed(1), rx:1.2,
      transform:'rotate(' + rr(0,180).toFixed(1) + ' ' + x.toFixed(1) + ' ' + y.toFixed(1) + ')',
      fill: rnd() > .5 ? '#c2360f' : '#e0561a', opacity:.92
    }));
    return true;
  });

  // chili-oil pools floating on the broth
  var oil = document.getElementById('oil');
  scatter(16, .1, 1.0, function(x,y){
    var s = rr(6, 26);
    var g = el('g', {'class':'float'});
    g.style.setProperty('--dur', rr(6,12).toFixed(2) + 's');
    g.style.setProperty('--delay', (-rr(0,9)).toFixed(2) + 's');
    g.appendChild(el('ellipse', {cx:x.toFixed(1), cy:y.toFixed(1), rx:s.toFixed(1), ry:(s*.42).toFixed(1),
      fill:'#ff7a20', opacity:(rr(.10,.26)).toFixed(2)}));
    g.appendChild(el('ellipse', {cx:(x-s*.2).toFixed(1), cy:(y-s*.12).toFixed(1), rx:(s*.55).toFixed(1), ry:(s*.2).toFixed(1),
      fill:'#ffcf8a', opacity:(rr(.08,.2)).toFixed(2)}));
    oil.appendChild(g);
    return true;
  });

  /* ---------- pointer state ---------- */
  var pointer = { x:0.5, y:0.5, px:0.5, py:0.5, vx:0, vy:0, active:false };
  var tilt = document.getElementById('tilt');
  var lightG = document.getElementById('light');

  function onMove(cx, cy){
    pointer.x = cx / window.innerWidth;
    pointer.y = cy / window.innerHeight;
    pointer.active = true;
  }
  if (!reduce){
    window.addEventListener('pointermove', function(e){ onMove(e.clientX, e.clientY); }, {passive:true});
    window.addEventListener('pointerdown', function(e){ onMove(e.clientX, e.clientY); splash(e.clientX, e.clientY); }, {passive:true});
    window.addEventListener('pointerleave', function(){ pointer.active = false; }, {passive:true});
  }

  /* ---------- ripple on the broth when you touch it ---------- */
  var ripples = document.getElementById('ripples');
  var svg = document.querySelector('svg.bowl');
  function splash(cx, cy){
    var r = svg.getBoundingClientRect();
    if (!r.width) return;
    // map screen -> viewBox (preserveAspectRatio meet)
    var s = Math.min(r.width/1000, r.height/760);
    var ox = r.left + (r.width - 1000*s)/2, oy = r.top + (r.height - 760*s)/2;
    var vx = (cx - ox)/s, vy = (cy - oy)/s;
    var dx = (vx - CX)/272, dy = (vy - CY)/74;
    if (dx*dx + dy*dy > 1.05) return; // only inside the bowl

